class ZoneInferencePlot:
    def __init__(
        self,
        cfg: AppConfig,
        model_repo: str,
        revision: Optional[str] = None,
        subfolder: Optional[str] = None,
        max_new_tokens: int = 64,
        do_sample: bool = False,
        temperature: float = 0.8,
        top_p: float = 0.95,
    ):
        self.cfg = cfg
        self.model = ModelInference(
            model_repo, 
            revision, 
            subfolder, 
            max_new_tokens=max_new_tokens, 
            do_sample=do_sample, 
            temperature=temperature, 
            top_p=top_p
        )
    
    def _inference(
        self,
        prompt,
        n_samples: int = 8
    )-> List[str]:
        return self.model.generate_samples(prompt, n_samples)
        
            
